INSERT INTO public.dc_projects
(slug,name,operator,developer,town,address_line,postcode,local_authority,nation,region,country,index_region_slug,planning_authority,planning_reference,status,planning_decision,decision_date,facility_type,project_type,ai_relevance,capacity_mw,it_capacity_mw,capacity_unit,capacity_definition,floor_area_sqm,investment_gbp,announced_date,construction_start_date,actual_operational_date,latitude,longitude,confidence_level,verified,last_verified_at,status_publication,display_order,summary,key_facts,sources,duplicate_reviewed,admin_notes)
VALUES
('google-waltham-cross','Google Waltham Cross data centre','Google','Google','Waltham Cross',NULL,NULL,'Broxbourne Borough Council','england','East of England','United Kingdom','south-east-england',NULL,NULL,'operational',NULL,NULL,'hyperscale','data_centre','medium',NULL,NULL,'MW','not_disclosed',NULL,NULL,DATE '2024-01-18',NULL,DATE '2025-09-16',NULL,NULL,'high',false,DATE '2026-10-03','draft',200,'Google''s first UK data centre, on a 33-acre site at Waltham Cross, Hertfordshire, which Google bought in October 2020. Construction of the $1bn (about £790m) facility was announced on 18 January 2024. It was opened by the Chancellor on 16 September 2025 as part of Google''s two-year £5bn UK investment, to support Google Cloud, Workspace, Search and Maps, including AI services. Google gives no capacity figure.','[]'::jsonb,'[{"title": "Google opens Waltham Cross data centre as part of two-year £5 billion investment in the UK", "url": "https://www.prnewswire.com/news-releases/google-opens-waltham-cross-data-centre-as-part-of-two-year-5-billion-investment-in-the-uk-to-help-power-its-ai-economy-302556707.html", "publisher": "Google (PR Newswire)", "date": "2025-09-16"}, {"title": "Waltham Cross data center", "url": "https://datacenters.google/locations/waltham-cross/", "publisher": "Google"}, {"title": "Our $1 billion investment in a new UK data centre", "url": "https://blog.google/company-news/inside-google/around-the-globe/google-europe/united-kingdom/google-1-billion-investment-in-a-new-uk-data-centre/", "publisher": "Google", "date": "2024-01-18"}]'::jsonb,false,'Held for review. Planning reference not retrieved; announcement date is Google''s 18 January 2024 $1bn announcement. The $1bn is not stored in investment_gbp because it is in US dollars. Check that the index region assignment matches other Hertfordshire records.'),
('google-north-weald-airfield','Google data centre, North Weald Airfield','Google','Google','North Weald',NULL,NULL,'Epping Forest District Council','england','East of England','United Kingdom','south-east-england','Epping Forest District Council',NULL,'approved','Outline planning permission granted by planning committee',DATE '2025-12-10','hyperscale','data_centre','unknown',NULL,NULL,'MW','not_disclosed',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'medium',false,DATE '2026-10-03','draft',201,'Outline plans for a Google data centre on 52 acres (21 ha) of North Weald Airfield, Essex, approved by Epping Forest District Council''s planning committee on 10 December 2025. Google bought the site for £88.2m in January 2024. A report to the planning committee estimated up to 780 local jobs, including around 200 direct jobs. No capacity figure has been published.','[]'::jsonb,'[{"title": "North Weald Airfield Google data centre is approved", "url": "https://www.bbc.com/news/articles/cx2552z9p1lo", "publisher": "BBC News", "date": "2025-12-14"}, {"title": "Google Data Centre", "url": "https://www.northweald-pc.gov.uk/google-data-centre/", "publisher": "North Weald Bassett Parish Council"}]'::jsonb,false,'Held for review. Need the EFDC application reference and decision notice.'),
('google-arena-essex-thurrock','Google data centre campus, Arena Essex, Purfleet-on-Thames','Google','Global Infrastructure UK Limited','Purfleet-on-Thames',NULL,NULL,'Thurrock Council','england','East of England','United Kingdom','south-east-england','Thurrock Council','25/00573/OUT','proposed','Hybrid application submitted; undetermined',NULL,'hyperscale','data_centre','unknown',NULL,NULL,'MW','not_disclosed',130500,NULL,NULL,NULL,NULL,NULL,NULL,'medium',false,DATE '2026-10-03','draft',202,'Hybrid application 25/00573/OUT to Thurrock Council for the former Arena Essex raceway and fishing lake, Arterial Road, Purfleet-on-Thames: full permission for demolition, remediation and access, and outline permission for up to four data centre buildings (up to 130,500 sq m GEA) plus an office building. Plans were submitted for Google by Global Infrastructure UK Ltd, which bought the 129-acre site in 2023. The site is a local wildlife site; Essex Wildlife Trust objects over habitat for rare bees and plants. Undecided as of September 2026.','[]'::jsonb,'[{"title": "Town and Country Planning public notice (25/00573/OUT)", "url": "https://www.thurrock.gov.uk/public-notices/town-and-country-planning-422", "publisher": "Thurrock Council", "date": "2025-10-16"}, {"title": "Thurrock data centre could harm rare bees, says Essex charity", "url": "https://www.bbc.com/news/articles/c24jrm0v8j4o", "publisher": "BBC News", "date": "2026-09-15"}]'::jsonb,false,'Held for review. Floor area is GEA of data centre buildings only.'),
('aws-didcot-north','Amazon Didcot North Data Centre Campus (former Didcot A Power Station)','Amazon Web Services','Amazon Data Services UK Limited (hybrid permission obtained by RWE)','Didcot',NULL,'OX11 7BF','Vale of White Horse District Council','england','South East','United Kingdom','south-east-england','Vale of White Horse District Council','P22/V1857/O; P25/V2197/RM','approved','Hybrid permission granted July 2025; reserved matters for four data centre buildings granted',DATE '2026-02-17','hyperscale','data_centre','unknown',NULL,NULL,'MW','not_disclosed',197000,NULL,NULL,NULL,NULL,NULL,NULL,'high',false,DATE '2026-10-03','draft',203,'Data centre campus on the former Didcot A Power Station site. RWE obtained hybrid permission (P22/V1857/O) in July 2025 for up to 197,000 sq m of data centre floorspace. Reserved matters for a four-building campus with gatehouse and plant (P25/V2197/RM) were granted on 17 February 2026, and the Environment Agency granted Amazon Data Services UK Limited a permit for standby generation (EPR/GP3127LV/A001) on 27 July 2026. Amazon has not given a site-specific investment or capacity figure; it forms part of AWS''s £8bn UK data centre investment for 2024 to 2028.','[]'::jsonb,'[{"title": "P25/V2199/S73 and related applications, Land at former Didcot A Power Station", "url": "https://planindex.co.uk/planning-applications/vale-of-white-horse/p25-v2199-s73", "publisher": "PlanIndex (Vale of White Horse register data)", "date": "2026-08-09"}, {"title": "OX11 7BF, Amazon Data Services UK Limited: environmental permit issued", "url": "https://www.gov.uk/government/publications/ox11-7bf-amazon-data-services-uk-limited-environmental-permit-issued-eprgp3127lva001", "publisher": "Environment Agency", "date": "2026-08-03"}, {"title": "Amazon plans data centre at former power plant site", "url": "https://www.bbc.com/news/articles/cg7y5g429jko", "publisher": "BBC News", "date": "2026-01-14"}, {"title": "Delivering Didcot Data Campus", "url": "https://deliveringdidcotdatacampus.co.uk/", "publisher": "RWE / project team"}]'::jsonb,false,'Held for review. Decision dates come from PlanIndex; confirm against the Vale of White Horse register. The permit uses postcode OX11 7BF; the planning register uses OX11 7HA. Construction start not confirmed.'),
('aws-thorney-lane-iver','Amazon Thorney Lane data centre, Thorney Business Park, Iver','Amazon Web Services','Amazon Data Services UK Limited','Iver','Thorney Business Park, Thorney Lane North','SL0 9EE','Buckinghamshire Council','england','South East','United Kingdom','slough-thames-valley','Buckinghamshire Council','PL/22/1775/FA','approved','Hybrid permission granted 29 May 2024 to the previous site owner; Amazon proposes a new full application',DATE '2024-05-29','hyperscale','data_centre','unknown',NULL,NULL,'MW','not_disclosed',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'medium',false,DATE '2026-10-03','draft',204,'Amazon Data Services UK Limited applied to the Environment Agency for a permit (EPR/MP3824MG/A001, advertised 3 June 2026) for emergency back-up generation at a data centre on Thorney Business Park, Iver: 36 main generators of up to 7.57 MWth thermal input each, plus two house generators. The permit documents cite an extant hybrid planning permission (PL/22/1775/FA), granted by Buckinghamshire Council on 29 May 2024 to the previous site owner: full permission for a first data centre building with backup generators and outline permission for further data centre buildings. Amazon will seek design changes through a new full application. Generator thermal input is not an IT-load figure and is not recorded as capacity.','[]'::jsonb,'[{"title": "SL0 9EE, Amazon Data Services UK Limited: environmental permit application advertisement", "url": "https://www.gov.uk/government/publications/sl0-9ee-amazon-data-services-uk-limited-environmental-permit-application-advertisement-eprmp3824mga001", "publisher": "Environment Agency", "date": "2026-06-03"}, {"title": "Thorney Lane Data Centre Emergency Back-Up Generation Facility: non-technical summary", "url": "https://consult.environment-agency.gov.uk/psc/sl0-9ee-amazon-data-services-uk-limited/supporting_documents/application-bespoke-sp3224lp-app-nts-non-technical-summary-final-2026-02-23-epr-mp3824mg-a001-020326pdf", "publisher": "Amazon Data Services UK Limited (permit application)", "date": "2026-02"}]'::jsonb,false,'Held for review. The previous owner who obtained PL/22/1775/FA is not named in the permit papers, and the new full application''s reference is not yet known. Developer field shows Amazon as the current applicant. Check for overlap with existing Iver records before publishing.'),
('cloudhq-lhr-didcot','CloudHQ LHR Campus, Didcot','CloudHQ','CloudHQ','Didcot',NULL,NULL,NULL,'england','South East','United Kingdom','south-east-england',NULL,NULL,'approved','Planning approval reported (October 2024)',NULL,'type_unconfirmed','data_centre','unknown',101,101,'MW','it_load',209032,1900000000,DATE '2024-10-14',NULL,NULL,51.62773,-1.2704,'medium',false,DATE '2026-10-03','draft',205,'A £1.9bn data centre campus by Washington DC-based CloudHQ on 37.5 acres of the former Didcot A power station grounds, welcomed by the Technology Secretary in October 2024. CloudHQ describes it as fully permitted and powered, with 101 MW of critical IT load, expandable to 300 MW, and 2.25m sq ft of space. The BBC reported 1,500 construction jobs and 100 permanent roles. Separate from Amazon''s Didcot North campus on the same former power station site.','[]'::jsonb,'[{"title": "Tech Secretary welcomes foreign investment in UK data centres", "url": "https://www.gov.uk/government/news/tech-secretary-welcomes-foreign-investment-in-uk-data-centres-which-will-spur-economic-growth-and-ai-innovation-in-britain", "publisher": "DSIT (GOV.UK)", "date": "2024-10-14"}, {"title": "LHR Campus", "url": "https://cloudhq.com/campus/lhr-campus-2/", "publisher": "CloudHQ"}, {"title": "Didcot £1.9bn data centre campus confirmed", "url": "https://www.bbc.com/news/articles/cn4znj8k29ro", "publisher": "BBC News", "date": "2024-10-15"}]'::jsonb,false,'Held for review. Planning authority and reference not retrieved; check whether consent came through the Vale of White Horse''s Didcot Technology Park Local Development Order. The 101 MW figure is CloudHQ''s own marketing figure for critical IT load. Construction status not confirmed.'),
('cyrusone-lon6-iver-heath','CyrusOne LON6, Iver Heath','CyrusOne','CyrusOne','Iver Heath',NULL,NULL,'Buckinghamshire Council','england','South East','United Kingdom','slough-thames-valley','Buckinghamshire Council',NULL,'approved','Full planning permission granted (reported July 2025)',NULL,'hyperscale','data_centre','unknown',90,90,'MW','it_load',63000,1200000000,DATE '2025-06-13',NULL,NULL,NULL,NULL,'medium',false,DATE '2026-10-03','draft',206,'CyrusOne''s sixth UK data centre: a 63,000 sq m hyperscale facility with 90 MW of IT capacity and 30,000 sq m of technical space, on a 41-acre former landfill site in the green belt between Denham Road, Seven Hills Road and the M25, opposite Pinewood Studios. CyrusOne is owned by US investors KKR and Global Infrastructure Partners. Full planning permission was reported in July 2025. CyrusOne states investment of more than £1.2bn, about 580 construction jobs and 540 operational roles. It planned to break ground in Q3 2026 with first capacity in early 2028; John F Hunt was reported in July 2026 to have won a £20m enabling and remediation package.','[]'::jsonb,'[{"title": "CyrusOne plans pioneering new London facility with sustainability at its core", "url": "https://www.cyrusone.com/resources/press-releases/cyrusone-plans-pioneering-new-london-facility-with-sustainability-at-its-core", "publisher": "CyrusOne", "date": "2025-06-13"}, {"title": "Massive new data centre planned on Green Belt by M25 in South Buckinghamshire", "url": "https://www.bucksfreepress.co.uk/news/24477240.m25-big-new-data-centre-planned-next-motorway/", "publisher": "Bucks Free Press"}, {"title": "John F Hunt bags £20m enabling works deal at giant data centre", "url": "https://www.constructionenquirer.com/2026/07/17/john-f-hunt-bags-20m-enabling-works-deal-at-giant-data-centre/", "publisher": "Construction Enquirer", "date": "2026-07-17"}]'::jsonb,false,'Held for review. Need the Buckinghamshire application reference and decision date; the permission is reported only by the planning consultant (Montagu Evans). Floor area: 63,000 sq m gross (Bucks Free Press); CyrusOne quotes 30,000 sq m of technical space. Change status to under construction once enabling works are confirmed to have started.'),
('ada-docklands-west-silvertown','Ada Docklands Data Campus, Royal Docks','Ada Infrastructure','Ada Infrastructure (Ares Management)','London',NULL,NULL,'London Borough of Newham','england','London','United Kingdom','london','London Borough of Newham',NULL,'under_construction','Hybrid permission (resolution 20 June 2024, issued December 2024); reserved matters for remaining buildings approved',NULL,'colocation','data_centre','unknown',NULL,NULL,'MW','unclear',NULL,NULL,NULL,DATE '2026-02-26',NULL,NULL,NULL,'medium',false,DATE '2026-10-03','draft',207,'A three-building data centre campus on a former paint factory site next to Tate & Lyle in the Royal Docks, Newham''s Strategic Development Committee resolved to grant the hybrid application on 20 June 2024, with detailed consent for Building 1, and permission was issued in December 2024. All three reserved matters applications were approved by May 2026, giving detailed permission for the whole site. Ada Infrastructure, part of US-based Ares Management''s digital infrastructure business, broke ground on 26 February 2026 and is building the first of three 70 MW buildings (210 MW in total, measure not defined), with the first due in mid-2028. The project expects 524 construction jobs.','[]'::jsonb,'[{"title": "Ada Infrastructure celebrates groundbreaking of its 210-megawatt Docklands data center campus in London", "url": "https://adainfrastructure.com/en-US/insights/news/ada-infrastructure-celebrates-groundbreaking-of-its-210-megawatt-docklands-data-center-campus-in-london", "publisher": "Ada Infrastructure", "date": "2026-02-26"}, {"title": "Ada Infrastructure approved to develop 210 MW data center campus in East London''s Royal Docks", "url": "https://adainfrastructure.com/en-US/insights/news/ada-infrastructure-approved-to-develop-210-mw-data-center-campus-in-east-londons-royal-docks", "publisher": "Ada Infrastructure", "date": "2024-06-20"}, {"title": "Docklands Data Campus", "url": "https://www.adadocklands.co.uk/docklands-data-campus/", "publisher": "Ada Infrastructure"}, {"title": "Latest news", "url": "https://www.adadocklands.co.uk/latest-news/", "publisher": "Ada Infrastructure", "date": "2026-05-06"}]'::jsonb,false,'Held for review. The 210 MW figure is not defined as IT load, so capacity_mw is left blank. Need the Newham application references.'),
('elsham-tech-park','Elsham Tech Park, former RAF Elsham Wolds',NULL,'Elsham Tech Park Ltd (Greystoke)','Elsham',NULL,NULL,'North Lincolnshire Council','england','Yorkshire and the Humber','United Kingdom','north-east-and-yorkshire','North Lincolnshire Council','PA/2025/643','approved','Outline planning permission approved unanimously by planning committee',NULL,'ai_hpc','data_centre','high',1000,1000,'MW','it_load',1500000,NULL,NULL,NULL,NULL,NULL,NULL,'medium',false,DATE '2026-10-03','draft',208,'Outline permission (PA/2025/643) for an AI data centre campus of up to 1 GW of IT load on 176 ha of the former RAF Elsham Wolds airfield near Scunthorpe, approved unanimously by North Lincolnshire Council''s planning committee in March 2026. The scheme has more than 1.5m sq m of floorspace in 15 data halls, battery storage, a 49.9 MW on-site energy centre and heat reuse for greenhouses. The council cites up to £10bn of private investment and 900 to 1,200 permanent jobs; the build cost is estimated at about £7.5bn. Construction is expected from 2027, with the first phase open in 2029. No operator is named.','[]'::jsonb,'[{"title": "''Billions of pounds'' of AI investment could bring hundreds of skilled jobs to North Lincolnshire", "url": "https://www.northlincs.gov.uk/news/billions-of-pounds-of-ai-investment-could-bring-hundreds-of-skilled-jobs-to-north-lincolnshire/", "publisher": "North Lincolnshire Council", "date": "2026-03-11"}, {"title": "UK''s biggest AI data centre plan approved", "url": "https://www.constructionenquirer.com/2026/03/12/uks-biggest-ai-data-centre-plan-approved/", "publisher": "Construction Enquirer", "date": "2026-03-12"}]'::jsonb,false,'Held for review. Committee decision date not confirmed (council news 11 March 2026). Not US-led; the developer is UK-based Greystoke.'),
('west-sleekburn-data-centre','West Sleekburn Data Centre',NULL,'Wansbeck Regeneration Ltd','West Sleekburn',NULL,NULL,'Northumberland County Council','england','North East','United Kingdom','north-east-and-yorkshire','Northumberland County Council','26/02160/OUTES','proposed','Outline application submitted; awaiting determination',NULL,'type_unconfirmed','data_centre','unknown',NULL,NULL,'MW','unclear',356500,3800000000,NULL,NULL,NULL,NULL,NULL,'medium',false,DATE '2026-10-03','draft',209,'Outline application 26/02160/OUTES (all matters reserved except access), submitted in June 2026 by Wansbeck Regeneration Ltd, for a data centre campus of up to 356,500 sq m GIA in three buildings on about 70 acres (28 ha) of agricultural land on part of the former GlaxoSmithKline site at West Sleekburn, south of the River Wansbeck. It includes up to 49.9 MW of gas generation as a bridging supply. Proposed operational capacity is reported as 384 MW (measure not defined). Investment is put at £3.8bn, with up to 785 direct jobs (Lichfields). The site is less than two miles from QTS''s Cambois campus. No operator is named.','[]'::jsonb,'[{"title": "Plans for Northumberland''s second AI data centre submitted", "url": "https://www.bbc.co.uk/news/articles/cwyek0jl80xo", "publisher": "BBC News", "date": "2026-06-20"}, {"title": "Plans in for West Sleekburn Data Centre", "url": "https://www.placenortheast.co.uk/plans-in-for-west-sleekburn-data-centre/", "publisher": "Place North East", "date": "2026-06-23"}, {"title": "Plans filed for three-building data center campus in Northumberland, UK", "url": "https://www.datacenterdynamics.com/en/news/plans-filed-for-three-building-data-center-campus-in-northumberland-uk/", "publisher": "DatacenterDynamics", "date": "2026-07-09"}, {"title": "Northumberland''s power-first campus test", "url": "https://data-central.co.uk/northumberlands-power-first-campus-test/", "publisher": "DataCentral", "date": "2026-06-22"}]'::jsonb,false,'Held for review. The 384 MW figure comes from Place North East (22 Sep 2026) and its measure is not defined.'),
('tbc-partners-factory-road-cambois','TBC Partners data centre, Factory Road, Cambois',NULL,'TBC Partners','Cambois',NULL,NULL,'Northumberland County Council','england','North East','United Kingdom','north-east-and-yorkshire','Northumberland County Council',NULL,'proposed','EIA screening opinion: full EIA required',NULL,'type_unconfirmed','data_centre','unknown',NULL,NULL,'MW','not_disclosed',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'low',false,DATE '2026-10-03','draft',210,'An early-stage proposal by TBC Partners for one or two data centre buildings, up to 30m high, on a 30-acre site at Factory Road, Cambois, between QTS''s campus and the West Sleekburn scheme. Northumberland County Council''s screening opinion, reported in September 2026, found that a full environmental impact assessment is required, citing cumulative traffic, protected-site and generator-emission impacts. Construction would take about 24 months, with operation expected between 2030 and 2035. No application has been submitted.','[]'::jsonb,'[{"title": "TBC Partners explores second Cambois data centre", "url": "https://www.placenortheast.co.uk/tbc-partners-explores-second-cambois-data-centre/", "publisher": "Place North East", "date": "2026-09-22"}]'::jsonb,false,'Held for review. Pre-application only; consider tracking without publishing.'),
('anthropic-teesworks-redcar','Anthropic data centre, Teesworks (former Redcar steelworks)','Anthropic',NULL,'Redcar',NULL,NULL,'Redcar and Cleveland Borough Council','england','North East','United Kingdom','north-east-and-yorkshire',NULL,NULL,'proposed','No planning application; land deal reported but unsigned',NULL,'ai_hpc','data_centre','high',NULL,NULL,'MW','not_disclosed',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'indicative',false,DATE '2026-10-03','draft',211,'Private Eye reported in June 2026 that Anthropic had agreed in principle to buy 222 acres of the Teesworks site for £1m an acre, plus £40m for an electricity link, with further payments if 1,400 MW of power is supplied by 31 December 2029. Tees Valley Mayor Ben Houchen said the deal had not yet been signed. Anthropic has not confirmed it. No planning application has been made, and the land and power figures are deal terms, not facility capacity.','[]'::jsonb,'[{"title": "Ben Houchen responds to Teesworks ''deal of the century''", "url": "https://northeastbylines.co.uk/business/ben-houchen-responds-to-teesworks-deal-of-the-century/", "publisher": "North East Bylines", "date": "2026-06-15"}]'::jsonb,false,'Held: unconfirmed land deal based on Private Eye reporting. Do not publish until Anthropic or Teesworks confirms, or a planning application appears. The Teesworks AI Growth Zone status is not confirmed on GOV.UK.'),
('microsoft-eggborough','Microsoft Eggborough datacentre (former Eggborough Power Station)','Microsoft','Microsoft','Eggborough',NULL,NULL,'North Yorkshire Council','england','Yorkshire and the Humber','United Kingdom','north-east-and-yorkshire','North Yorkshire Council',NULL,'proposed','Pre-application consultation (February 2024); application not traced',NULL,'hyperscale','data_centre','unknown',NULL,NULL,'MW','not_disclosed',NULL,NULL,DATE '2024-02-21',NULL,NULL,NULL,NULL,'low',false,DATE '2026-10-03','draft',212,'Microsoft consulted on a new datacentre on part of the former Eggborough Power Station site in February 2024; North Yorkshire Council described it as a 1.2m sq ft data centre. At the time it said it aimed to apply to North Yorkshire Council in mid-2024, clear the site by late 2026 and start construction in early 2027. No data centre planning application or later update has been traced. The 2025 applications on the wider power station site are for other employment plots by Core 62 (Eggborough) Ltd.','[]'::jsonb,'[{"title": "Eggborough datacentre project updates", "url": "https://local.microsoft.com/blog/eggborough-datacentre-project-updates/", "publisher": "Microsoft Local", "date": "2024-02-28"}, {"title": "Executive Member for Open to Business report", "url": "https://edemocracy.northyorks.gov.uk/documents/s30325/Executive%20Mewmber%20for%20Open%20to%20Business%20-%20Councillor%20Derek%20Bastiman.pdf", "publisher": "North Yorkshire Council", "date": "2024-05-15"}, {"title": "Microsoft ramps up UK data center expansion with plans for new Yorkshire site", "url": "https://www.itpro.com/infrastructure/data-centres/microsoft-ramps-up-uk-data-center-expansion-with-plans-for-new-yorkshire-site", "publisher": "ITPro", "date": "2024-03-01"}]'::jsonb,false,'Held: search the North Yorkshire Council register for a planning application before publishing.'),
('thames-valley-park-earley','Thames Valley Park Data Centre, Earley',NULL,NULL,'Earley',NULL,'RG6 1WG','Wokingham Borough Council','england','South East','United Kingdom','slough-thames-valley','Wokingham Borough Council',NULL,'proposed','Pre-application consultation (July 2026); application expected autumn 2026',NULL,'type_unconfirmed','data_centre','unknown',72,72,'MW','it_load',NULL,200000000,NULL,NULL,NULL,NULL,NULL,'low',false,DATE '2026-10-03','draft',213,'A proposal for a data centre of about 72 MW IT load on about 5.3 ha at Thames Valley Park, Earley, replacing three office buildings occupied by Microsoft. The project team consulted in July 2026 and planned to apply to Wokingham Borough Council in autumn 2026. It cites more than £200m of construction investment, up to 245 construction jobs and at least 115 operational roles. The BBC reports Microsoft is not involved. A petition against it has more than 4,000 signatures.','[]'::jsonb,'[{"title": "Thames Valley Park Data Centre", "url": "https://www.tvpdc.co.uk/", "publisher": "Project team"}, {"title": "Thousands sign petition against proposed data centre", "url": "https://www.bbc.com/news/articles/cly4vqzkwzyo", "publisher": "BBC News", "date": "2026-09-01"}, {"title": "Data centre planned for Microsoft UK HQ at Thames Valley Park", "url": "https://www.bbc.co.uk/news/articles/cpv3xremevlo", "publisher": "BBC News", "date": "2026-07-02"}]'::jsonb,false,'Held: developer not named. Check whether the application has been lodged.'),
('vantage-lhr2-park-royal','Vantage Data Centers LHR2, Park Royal','Vantage Data Centers','Vantage Data Centers','London',NULL,NULL,NULL,'england','London','United Kingdom','london',NULL,NULL,'operational',NULL,NULL,'colocation','data_centre','unknown',20,20,'MW','it_load',18000,250000000,DATE '2025-09-11',NULL,NULL,NULL,NULL,'medium',false,DATE '2026-10-03','draft',214,'Vantage Data Centers'' second London campus, a £250m, 20 MW IT facility with 18,000 sq m (194,000 sq ft) in Park Royal. Vantage, headquartered in Denver, announced on 11 September 2025 that it would open at the end of that month; trade reports since describe it as operating.','[]'::jsonb,'[{"title": "Vantage Data Centers announces opening of second London campus with landmark public art installation", "url": "https://vantage-dc.com/news/vantage-data-centers-announces-opening-of-second-london-campus-with-landmark-public-art-installation/", "publisher": "Vantage Data Centers", "date": "2025-09-11"}]'::jsonb,false,'Held for review. Local planning authority (Ealing, Brent or OPDC) and opening date not confirmed. Check for overlap with premier-park-park-royal (SEGRO) before publishing.')
