-- DRAFT records for 15 projects missing from the UK data centre tracker (research review, 3 October 2026).
-- Every row is inserted with status_publication = 'draft', so nothing appears on the public site
-- until you publish it in the admin. Run STEP 1 first, check for duplicates, then run STEP 2.
-- Rows whose slug (or planning authority + reference) already exists are skipped.

-- STEP 1 (read-only): possible duplicates already in the register
SELECT slug, name, status, status_publication FROM public.dc_projects
WHERE slug IN ('google-waltham-cross', 'google-north-weald-airfield', 'google-arena-essex-thurrock', 'aws-didcot-north', 'aws-thorney-lane-iver', 'cloudhq-lhr-didcot', 'cyrusone-lon6-iver-heath', 'ada-docklands-west-silvertown', 'elsham-tech-park', 'west-sleekburn-data-centre', 'tbc-partners-factory-road-cambois', 'anthropic-teesworks-redcar', 'microsoft-eggborough', 'thames-valley-park-earley', 'vantage-lhr2-park-royal')
   OR name ILIKE ANY (ARRAY['%Waltham Cross%','%North Weald%','%Arena Essex%','%Thurrock%','%Didcot%','%Thorney%','%CloudHQ%','%LON6%','%CyrusOne%','%Ada %','%Docklands%','%Elsham%','%Sleekburn%','%Factory Road%','%Teesworks%','%Redcar%','%Eggborough%','%Thames Valley Park%','%LHR2%','%Vantage%London%'])
ORDER BY name;

-- STEP 2: insert as drafts
ON CONFLICT DO NOTHING;

-- STEP 3 (read-only): confirm the drafts
SELECT slug, status, status_publication, confidence_level FROM public.dc_projects
WHERE slug IN ('google-waltham-cross', 'google-north-weald-airfield', 'google-arena-essex-thurrock', 'aws-didcot-north', 'aws-thorney-lane-iver', 'cloudhq-lhr-didcot', 'cyrusone-lon6-iver-heath', 'ada-docklands-west-silvertown', 'elsham-tech-park', 'west-sleekburn-data-centre', 'tbc-partners-factory-road-cambois', 'anthropic-teesworks-redcar', 'microsoft-eggborough', 'thames-valley-park-earley', 'vantage-lhr2-park-royal') ORDER BY display_order;
